<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Resigned Employees</title><link rel="stylesheet" href="../public/css/style.css"><link rel="stylesheet" href="../public/css/dashboard.css?v=20260909-2"><link rel="stylesheet" href="../public/css/employee-documents-fixes.css?v=20260921-1"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><style><?php $template=file_get_contents(__DIR__.'/employee_documents_expiring.php');if(preg_match('/<style>(.*?)<\/style>/s',$template,$match))echo $match[1];?>.status-resigned{background:#eceff2;color:#596874}</style><link rel="stylesheet" href="../public/css/module-theme.css?v=18">
<script defer src="../public/js/nursync-ui.js?v=4"></script></head><body class="module-ui"><?php include '../includes/employee_documents_sidebar.php';?><main class="ed-expiring-main"><header class="page-head"><div><h1><i class="fa-solid fa-user-slash"></i> Resigned Employees</h1><p>Former employees retained for document history and audit records.</p></div><span class="badge status-resigned"><?=count($resignedEmployees)?> EMPLOYEE<?=count($resignedEmployees)===1?'':'S'?></span></header><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Employee ID</th><th>Employee</th><th>Position</th><th>Department</th><th>Employment Status</th><th>Date Hired</th><th>Account Status</th></tr></thead><tbody><?php foreach($resignedEmployees as$employee):?><tr><td><?=h($employee['employee_id']?:'—')?></td><td><strong><?=h($employee['name'])?></strong></td><td><?=h($employee['position']?:'—')?></td><td><?=h(str_replace('_',' ',$employee['department']??''))?></td><td><?=h($employee['employment_status']?:'—')?></td><td><?=edDate($employee['date_hired'])?></td><td><span class="badge status-resigned">RESIGNED</span></td></tr><?php endforeach;?><?php if(!$resignedEmployees):?><tr><td colspan="7" class="empty">No employees are marked as resigned.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
